// Copyright (c) 2026 Roshan. All rights reserved.// Proprietary license — see LICENSE file for details.package com.roshan.persona.vision.screenimport timber.log.Timberimport com.roshan.persona.brain.llm.provider.FinishReasonimport com.roshan.persona.brain.llm.provider.GenerationConfigimport com.roshan.persona.brain.llm.provider.LocalLlmProviderimport com.roshan.persona.common.Resultimport com.roshan.persona.vision.ocr.OcrBlockimport javax.inject.Injectimport javax.inject.Singleton/** * NOUS — LLM Screen Summarizer (Module 6 v4 — Step 6.6, REAL implementation). * * Generates a semantic summary of the current screen by calling the on-device * [LocalLlmProvider] (Module 4's Llama.cpp via JNI). Replaces * [FakeScreenSummarizer] in the Hilt graph. * * ## Pipeline * * ``` * (ocrText, uiElements, ocrBlocks) → *   ↓ * 1. Build prompt: *    "Summarize this screen for a blind user. OCR text: ... UI elements: ..." *   ↓ * 2. Call LocalLlmProvider.generate(prompt, FAST, onToken={}) → Result<GenerationResult> *   ↓ * 3. Parse result: *    - Success → use generated text as summary *    - Failure → fall back to template-based summary *   ↓ * 4. Return ScreenSummary(summary, spokenSummary, confidence) * ``` * * ## Privacy * *  - LLM inference is **100% on-device** (Llama.cpp). *  - No screen content ever leaves the device. *  - The OCR text passed to the LLM is processed in RAM and discarded *    immediately after summary generation. * * @see <a href="docs/strategy/module-6-vision-strategy-v4.md">§Upgrade 1: Visual Screen Reader</a> */@Singletonclass LlmScreenSummarizer @Inject constructor(    private val llmProvider: LocalLlmProvider,) : ScreenSummarizer {    override suspend fun summarize(        ocrText: String,        uiElements: List<UiElement>,        ocrBlocks: List<OcrBlock>,    ): ScreenSummary {        val prompt = buildPrompt(ocrText, uiElements)        return try {            val result = llmProvider.generate(                prompt = prompt,                config = GenerationConfig.FAST,                onToken = {},  // No streaming — we want the full summary.            )            when (result) {                is Result.Success -> {                    val text = result.data.text.trim()                    if (text.isNotBlank()) {                        Timber.tag(TAG).d("LLM summary generated (${text.length} chars, " +                            "${result.data.tokensPerSecond.toInt()} tok/s, ${result.data.durationMs}ms).")                        ScreenSummary(                            summary = text,                            spokenSummary = text,                            confidence = 0.90f,                        )                    } else {                        Timber.tag(TAG).w("LLM returned empty summary — using fallback.")                        fallbackSummary(ocrText, uiElements)                    }                }                is Result.Failure -> {                    Timber.tag(TAG).w("LLM call failed: ${result.error.code} — using fallback.")                    fallbackSummary(ocrText, uiElements)                }                is Result.Partial -> {                    // Result.Partial wraps a SkillOutput, not a GenerationResult.                    // LocalLlmProvider.generate() returns Result<GenerationResult>,                    // so this branch should never trigger — handle defensively.                    Timber.tag(TAG).w("LLM call returned Partial — using fallback.")                    fallbackSummary(ocrText, uiElements)                }            }        } catch (t: Throwable) {            Timber.tag(TAG).e("LLM summarization threw — using fallback.", t)            fallbackSummary(ocrText, uiElements)        }    }    // ─── Internal ──────────────────────────────────────────────────────────    /**     * Build the LLM prompt: a system instruction + screen content (OCR text +     * UI elements). Designed to fit within a 2k-context small model (Qwen 0.5B).     */    private fun buildPrompt(ocrText: String, uiElements: List<UiElement>): String {        val truncatedOcr = if (ocrText.length > MAX_OCR_CHARS) {            ocrText.take(MAX_OCR_CHARS) + "... [truncated]"        } else {            ocrText        }        val uiList = uiElements            .take(MAX_UI_ELEMENTS)            .joinToString("\n") { el ->                val pos = el.boundingBoxPosition                val text = el.text?.let { " \"$it\"" } ?: ""                "  - ${el.label}$text at $pos"            }        return buildString {            appendLine(SYSTEM_INSTRUCTION)            appendLine()            appendLine("## Screen OCR Text")            appendLine(truncatedOcr.ifBlank { "(no text detected)" })            appendLine()            appendLine("## UI Elements (${uiElements.size} detected, showing ${minOf(uiElements.size, MAX_UI_ELEMENTS)})")            appendLine(uiList.ifBlank { "(no UI elements detected)" })            appendLine()            appendLine("## Task")            appendLine("Write a single 1-2 sentence summary of what's on this screen, suitable for a blind user to hear via TTS. Do not list elements; describe the screen's purpose.")        }    }    /**     * Template-based fallback used when the LLM is unavailable or fails.     *     * This matches the fallback logic in [ScreenUnderstandingEngine.fallbackSummary]     * so behavior is consistent whether the LLM is on or off.     */    private fun fallbackSummary(ocrText: String, uiElements: List<UiElement>): ScreenSummary {        val elementCount = uiElements.size        val textPreview = ocrText.take(100)        val summary = when {            elementCount > 0 && textPreview.isNotBlank() ->                "Found $elementCount UI elements. Visible text: $textPreview"            elementCount > 0 ->                "Found $elementCount UI elements. No readable text detected."            textPreview.isNotBlank() ->                "Screen text: $textPreview"            else ->                "I can't read anything on this screen."        }        return ScreenSummary(            summary = summary,            spokenSummary = summary,            confidence = 0.50f,  // Low confidence — fallback.        )    }    private companion object {        private const val TAG = "LlmScreenSummarizer"        /** Cap OCR text length to keep prompt within small-model context (2k tokens). */        private const val MAX_OCR_CHARS = 1000        /** Cap UI elements listed in prompt. */        private const val MAX_UI_ELEMENTS = 25        /**         * System instruction for the LLM (non-const — `.trimIndent()` is a         * runtime call, not a compile-time constant expression).         */        private val SYSTEM_INSTRUCTION: String = """You are NOUS, a helpful on-device screen reader for blind users.Your job: summarize what's on the user's Android screen in 1-2 short sentences.Be specific (mention app names, message senders, numbers). Be brief.Example output: "You're on the WhatsApp chat with Mom. She sent a photo 2 minutes ago."        """.trimIndent()    }}